<?php require __DIR__.'/lib.php';admin_init();$error='';$success='';try{if(isset($_GET['token'])){$_SESSION['reset_grant']=people_reset_grant((string)$_GET['token']);header('Location: password.php?reset=1');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){admin_csrf();if(($_POST['action']??'')==='forgot'){people_recovery_request(trim((string)($_POST['username']??'')),trim((string)($_POST['phone']??'')));$success='Nếu thông tin khớp tài khoản, yêu cầu đã được chuyển đến quản trị viên. Liên hệ quản trị viên để nhận liên kết đặt lại.';}elseif(isset($_SESSION['reset_grant'])){people_reset_password($_SESSION['reset_grant'],$_POST);unset($_SESSION['reset_grant']);$success='Đã đặt lại mật khẩu. Bạn có thể đăng nhập với mật khẩu mới.';}}}catch(Throwable $e){$code=in_array($e->getCode(),[400,401,403,409,429],true)?$e->getCode():500;http_response_code($code);$error=$code===500?'Chưa xử lý được yêu cầu. Vui lòng thử lại.':$e->getMessage();}$reset=isset($_GET['reset'],$_SESSION['reset_grant']);?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Đặt lại mật khẩu · THE VICTOR</title><link rel="stylesheet" href="people.css?v=18"></head><body><main><a class="brand" href="/lamviec/">THE VICTOR</a><section class="card narrow"><h1><?=$reset?'Đặt mật khẩu mới':'Quên mật khẩu'?></h1><?php if($error):?><p class="error" role="alert"><?=h($error)?></p><?php endif;?><?php if($success):?><p class="notice" role="status"><?=h($success)?></p><?php else:?><form method="post"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input type="hidden" name="action" value="<?=$reset?'reset':'forgot'?>"><?php if($reset):?><label>Mật khẩu mới<input name="new_password" type="password" autocomplete="new-password" minlength="12" maxlength="72" required></label><label>Nhập lại mật khẩu mới<input name="confirmation" type="password" autocomplete="new-password" minlength="12" maxlength="72" required></label><?php else:?><label>User (tên tài khoản)<input name="username" autocomplete="username" maxlength="50" required></label><label>Số điện thoại trong hồ sơ<input name="phone" type="tel" autocomplete="tel" required></label><p class="muted">Quản trị viên kiểm tra yêu cầu và cấp liên kết dùng một lần, có hiệu lực 30 phút. Nếu chưa có số điện thoại trong hồ sơ hoặc quên tài khoản quản trị viên gốc, liên hệ người quản lý cửa hàng/hosting.</p><?php endif;?><button class="primary"><?=$reset?'Lưu mật khẩu mới':'Gửi yêu cầu đặt lại'?></button></form><?php endif;?><p><a href="/lamviec/">Về trang đăng nhập</a></p></section></main></body></html>
